```{.r .cell-code}
make_sine <- function(x, freq = 1){
  # if there's no `freq` column
  # set `freq` to 1.
  y = sin(
        (freq * x * 2 * pi)
      )
}
```
:::



::: {.cell}

```{.r .cell-code}
make_moving_sine <- function(x, freq, t){
  sin(
    (freq * (x - t) * 2 * pi)
  )
}
```
:::



::: {.cell}

```{.r .cell-code}
expand_grid(
  x = seq(0,1, length = 100),
  freq = c(1, 2, 4),
  t = seq(0, 3, length = 100)
) |> 
  mutate(
    .by = freq,
    y = make_moving_sine(x, freq, t)
  ) |> 
  v$vplot() |> 
  v$mark_line(
    x = x,
    y = y,
    color = freq
  ) |> 
  v$transition_time(
    t
  ) |> 
  v$scale_color_continuous(
    palette = "Plasma"
  ) |> 
  v$animate(
    nframes = 200
  ) |> 
  v$anim_save(
    filename = "test.gif"
  )
```
