```{.r .cell-code}
make_moving_disp <- function(x, freq=1, t=0){
  cos(
    (freq * (x - t)* 2 * pi)
  )
}

make_disp_df <- function(df,freq=1,t=0){
  df |> 
    mutate(
      x = x + (make_moving_disp(
        x, freq, t
      ) * 0.09),
      disp = make_moving_disp(
        x, freq, t
      ),
      t = t
    )
}
```
