::: {.cell}

```{.r .cell-code}
tibble(
  x = runif(10000, max = 2),
  y = runif(10000)
) |> 
  mutate(
    id = row_number()
  )->
  air


air |> 
  filter(
    between(x, 0.99, 1.1)
  ) |> 
  pull(id) |> 
  sample(20) ->
  chosen

air |> 
  mutate(
    mark = id %in% chosen
  ) -> 
  air

map(
  seq(0, 2.5*pi, length = 100),
  ~make_disp_df(
    df = air, 
    freq = 1,
    t = .x
  )
) |> 
  list_rbind() ->
  big_df
```
:::



